```go
package main

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"log"
	"os"

	"github.com/blang/semver/v4"
)

type StructToAvroOptions struct {
	File     string
	Struct   string
	Output   string
	Version  *semver.Version
}

func (o StructToAvroOptions) ParseAndGenerate() error {
	fileBytes, err := ioutil.ReadFile(o.File)
	if err != nil {
		return fmt.Errorf("failed to read file: %w", err)
	}
	code := string(fileBytes)

	// Compile the code to get the AST
	fset := token.NewFileSet()
	root, err := parser.ParseFiles(fset, []byte(code), token.AllFlags)
	if err != nil {
		return fmt.Errorf("failed to compile code: %w", err)
	}

	// Find the struct definition
	for _, decl := range root.Decls {
		if def, ok := decl.(*ast.FuncDecl); ok && def.Name.Name == o.Struct {
			structDef := ast.ToInterface(def.Type)
			break
		}
	}

	if structDef == nil {
		return fmt.Errorf("struct not found")
	}

	// Generate Avro schema based on the struct definition
	schema, err := generateAvroSchema(structDef)
	if err != nil {
		return fmt.Errorf("failed to generate Avro schema: %w", err)
	}

	// Write the Avro schema to a file
	outFile, err := os.Create(o.Output + ".avsc")
	if err != nil {
		return fmt.Errorf("failed to create output file: %w", err)
	}
	defer outFile.Close()

	err = json.NewEncoder(outFile).Encode(schema)
	if err != nil {
		return fmt.Errorf("failed to encode schema: %w", err)
	}

	return nil
}

func generateAvroSchema(typeInfo interface{}) (*schema.AvroSchema, error) {
	switch t := typeInfo.(type) {
	case *ast.InterfaceType:
		typeName := t.Name.Name
		var fields []interface{}
		for i, fieldDef := range t.Fields.List {
			fieldName := fieldDef.Names[0].String()
			fieldType, ok := fieldDef.Type.(*ast.StarExpr)
			if !ok {
				return nil, fmt.Errorf("field type must be a pointer to another type")
			}
			fieldType := fieldType.X.Type

			fieldValue, err := generateAvroSchema(fieldType)
			if err != nil {
				return nil, err
			}

			fields = append(fields, &schema.Field{
				Name: fieldName,
				Type: fieldValue,
			})
		}

		return &schema.AvroSchema{
			Name:    typeName,
			Fields:  fields,
			Nullable: true,
		}, nil
	default:
		return nil, fmt.Errorf("unsupported type")
	}
}

func main() {
	options := StructToAvroOptions{
		File:     "your_go_file.go",
		Struct:   "YourStruct",
		Output:   "output/",
		Version:  semver.MustParse("1.0.0"),
	}

	if err := options.ParseAndGenerate(); err != nil {
		log.Fatalf("Error generating Avro schema: %v\n", err)
	}

	fmt.Printf("Generated Avro schema successfully.\n")
}
```

