```java
import java.util.Scanner;

public class RetrieveInputExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("Please enter an integer:");

        // Read the input until a valid integer is entered
        while (!scanner.hasNextInt()) {
            try {
                int userChoice;
                System.out.print("Invalid input! Please enter a number: ");
                userChoice = scanner.nextInt();

                // Process the input (e.g., add it to a list)
                processInput(userChoice);
            } catch (InputMismatchException e) {
                System.err.println(e.getMessage());
            }
        }

        // Close the scanner
        scanner.close();

        // Now you can safely call other methods on the scanner instance
        String userInput = scanner.nextLine();
        System.out.println("User input after processing: " + userInput);
    }

    private static void processInput(int value) {
        System.out.println("Processing input: " + value);
        // Add logic here to process the input
    }
}
```

